local _, WFJ = ...
WFJ.Data.add("quest", {
  [90116] = { "Fili sacri", "Ottieni dei Dawnwoven Fabric tessendo stoffa in rotoli vicino al Crusader's Loom. Torna da Taylor quando ne avrai abbastanza.", "Questo telaio è speciale. Lo sapevi? Tutti i nostri artigiani hanno fatto benedire gli attrezzi del mestiere dai nostri sommi sacerdoti.\n\nIn particolare, il telaio attira stoffe e fili sparsi destinati ai più sacri dei nostri paramenti cerimoniali. Col tempo ne raccoglieremo abbastanza per creare una nuova veste, e quei giorni sono motivo di festa, almeno per me.\n\nSe il procedimento ti incuriosisce, tessi qualche rotolo vicino al telaio e guarda la Luce all'opera.", nil, nil, 0xc5231693, 0x64619cbd, 0x049e6b14, nil, nil, "...mm" },
  [90487] = { "Antichi alleati", "Viaggia a ovest dalla grotta dell'eremita per trovare un avamposto di antichi e driadi sulle pendici basse del ⟦Mount Hyjal=Monte Hyjal⟧.", "{name}, ho poco altro da offrirti. Se hai intenzione di affrontare la lunga salita sulla montagna, farai bene a parlare con alcuni dei suoi antichi custodi.\n\nSegui la strada a ovest. Guarda a nord, verso la base della montagna. Alla fine vedrai un avamposto, un residuo dei guardiani che un tempo vagavano sui pendii. Lì c'è un Antico di nome Fraxinus. Lui e i suoi amici possono aiutarti.", nil, nil, 0x00eda785, 0xe01cf952, 0x868ea2c2, nil, nil, "...mm" },
  [90647] = { "Bastone della Montagna", "Porta il Bastone della Montagna a Tiala Biancachioma alla Vetta dell'Eternità.", "Con tutti gli ingredienti che hai raccolto ho potuto infondere al bastone che hai recuperato una nuova magia. Ora dovresti poterlo usare per contrastare la magia degli Dei Selvatici che Ve'han ha rubato con tanta sfacciataggine.\n\nDobbiamo però metterlo alla prova. Portalo alla druida nota come Tiala Biancachioma alla Vetta dell'Eternità. Forse potrà aiutarci.", nil, nil, 0x9af96789, 0x16e85ed9, 0x964a463f, nil, nil, "...mm" },
  [90702] = { "Tomba profanata", "Cerca nei dintorni il contenuto mancante della tomba.", "<Qualcuno, o qualcosa, ha rovistato nella terra, lasciando frammenti d'osso sparsi qua e là. Un incavo dalla forma strana conduce più in profondità nel terreno freddo e umido.\n\nQualcosa nella zona potrebbe aver causato il disturbo.>", nil, nil, 0x122854ff, 0xee590106, 0x0c5c29bc, nil, nil, "...mm" },
  [90750] = { "Ancora lavoro?", "Parla con il contadino per fargli sapere che il lavoro è finito.", "Le battaglie sono spesso lunghe e dure, guidate da chi è disposto a opporsi a una minaccia imminente e a guardare la morte in faccia.\n\nLa verità è che sono stati fatti molti sacrifici, non solo sul campo di battaglia. Spesso trascuriamo chi fa la sua parte per contribuire.\n\nLaggiù c'è un contadino di nome... be', a pensarci bene, non so nemmeno come si chiami. Che razza di persona sono? Ci ha tenuti ben curati e nutriti per tutta la nostra permanenza.\n\nPotresti parlargli? Digli che il lavoro è finito.", nil, nil, 0x4489f9ed, 0x38a33249, 0x28f0afda, nil, nil, "...mm" },
  [90789] = { "⟦Scalebeard=Barbascaglia⟧", "Recupera la ⟦Prismatic Shell=Conchiglia Prismatica⟧ per l'⟦Archmage Xylem=Arcimago Xylem⟧. L'arcimago risiede in una torre in cima alle scogliere di Azshara.", "Non c'è molto tempo, {name}! I miei incantesimi di scrutamento hanno rivelato una potente fonte di magia. Non posso lasciare la torre e ti chiederei di uccidere la vile creatura in possesso di questo artefatto.\n\nLa bestia è nota come ⟦Scalebeard=Barbascaglia⟧ e si nasconde in una caverna nella ⟦Bay of Storms=Baia delle Tempeste⟧. Riducilo in cenere e prendi la conchiglia prismatica dalla sua tana.", nil, nil, 0xcd852ff9, 0xe0e3c89c, 0x86fd647a, nil, nil, "...mm" },
  [90813] = { "Filone fortunato!", "Trova qualcuno che possa valutare il Cristallo Enorme.", "<Il grosso pezzo di cristallo è ancora più pesante di quanto sembri. Pur sembrando un bel premio, la sua vera natura ti è ignota. Qualcuno esperto di geologia potrebbe dirti cosa hai davvero trovato.>", nil, nil, 0x89afa7ee, 0x45a72cf5, 0x055b1f5b, nil, nil, "...mm" },
  [90854] = { "Cuoio per il maltempo", "Porta $N1 Potenziamento d'Armatura Duro e $N2 ⟦Cured Rugged Hide=Pelle Dura Trattata⟧ a Zet'gan nella Selva Antica, sul ⟦Mount Hyjal=Monte Hyjal⟧.", "Vivere nelle terre selvagge per cinque anni, mon, ha messo a dura prova le nostre scorte. Abbiamo dovuto costruire 'sto posto da zero! Ci servirebbero le tue abilità di conciatore.\n\nDevo riparare alcune tende ed edifici e rattoppare qualche armatura. Portami due Potenziamenti d'Armatura Duri e una ⟦Cured Rugged Hide=Pelle Dura Trattata⟧ e ti aiuto a trasformarla in qualcosa di speciale.", nil, nil, 0x8cba0394, 0x1cb3933a, 0xe948817e, nil, nil, "...mm" },
  [90865] = { "Occhi dei guardiani", "Recupera $N1 Occhio del Guardiano per Eluneth.", "Appena a nord di qui giacciono le rovine di battaglie passate. Rimane una presenza del Flagello in diminuzione.\n\nSebbene i non morti senza mente siano già una minaccia, i guardiani tengono un occhio vigile su chi entra nella zona, rendendo ancora più difficile eliminare la minaccia del Flagello.\n\nElimina la minaccia prendendo a questi guardiani ciò che hanno di più prezioso.", nil, nil, 0x00105bc6, 0x90eb674f, 0x50a79b26, nil, nil, "...mm" },
  [90902] = { "Riscoprire la Luce", "Cura $N1 ⟦Injured Deathguard=Guardia della Morte Ferita⟧ con la tua abilità ⟦Holy Light=Luce Sacra⟧.", "È un orgoglio per me accogliere tra le nostre file <un/una> nuov<o/a> paladin<o/a> appena risort<o/a>. Mentre ritrovi il legame con la Luce, potresti notare che certe abilità che un tempo ti venivano naturali ora possono causarti un dolore considerevole, in particolare quelle che incanalano la Luce per curare te stess<o/a> o gli altri.\n\nL'unico modo per aggirare il problema è, purtroppo, attraversarlo. Come ogni muscolo atrofizzato, devi superare il dolore ed esercitare la carne perché torni a funzionare appieno.", "La padronanza della luce tornerà, col tempo.", "Il dolore non è una novità per chi ha sopportato la morte, e per questo i Reietti vi resistono particolarmente bene. Il dolore ha anche un potere purificatore, che dovresti accogliere come un segno d'onore e come la prova che sei davvero ancora al servizio della Luce, nonostante la tua nuova condizione.\n\nStammi bene e cammina di nuovo nella Luce, {class}.", 0xd0181974, 0x52f98d38, 0xcb54b8cd, 0x89566d7b, 0x32977739, "....." },
})
